"""Chapter 9: Alkynes (50 multiple choice + 50 free response)."""
from qb import *

CIS = 'C/C=C\\C'
TRANS = 'C/C=C/C'


def build(b):
    # ------------------------------------------------------------ 9.1 / 9.2
    b.mc('9.1', 1, 'How many σ and π bonds make up a carbon-carbon triple bond?', 'One σ and two π', ['Two σ and one π', 'Three σ', 'Three π'], 'A triple bond is one σ bond plus two π bonds.')
    b.mc('9.1', 1, 'What is the geometry around each carbon of a triple bond?', 'Linear (180°)', ['Trigonal planar (120°)', 'Tetrahedral (109.5°)', 'Bent'], 'sp hybridization gives a linear arrangement.')
    b.mc('9.1', 2, 'What is the hybridization of the carbons of an alkyne triple bond?', 'sp', ['sp²', 'sp³', 'p'], 'Two sp orbitals form two σ bonds; two p orbitals form the two π bonds.')
    b.mc('9.1', 2, 'Which compound has a C-C-C bond angle of 180°?', 'Propyne', ['Propene', 'Propane', 'Cyclopropane'], 'The sp carbons of propyne are linear with their neighbours.', img=S('CC#C'))
    b.mcring('9.2', 1, 'What is the IUPAC name of the compound shown?', 'CCC#C', 'but-1-yne', ['but-2-yne', 'propyne', 'pent-1-yne'], 'The chain has four carbons with the triple bond starting at C1.')
    b.mcring('9.2', 2, 'What is the IUPAC name of the compound shown?', 'CC#CC', 'but-2-yne', ['but-1-yne', 'butyne', 'dimethylethene'], 'The triple bond is in the middle of a four-carbon chain.')
    b.mcring('9.2', 2, 'What is the IUPAC name of the compound shown?', 'CC#CC(C)C', '4-methylpent-2-yne', ['2-methylpent-2-yne', '3-methylpent-1-yne', '4-methylpent-1-yne'], 'Number from the end nearest the triple bond.')
    b.mcring('9.2', 3, 'What is the IUPAC name of the compound shown?', 'CCC(C)C#CC(C)C', '2,5-dimethylhept-3-yne', ['2,6-dimethylhept-3-yne', '2,5-dimethyloct-3-yne', '3,5-dimethylhept-1-yne'], 'The triple bond gets the lowest locant (3), then the substituents.')
    b.mc('9.2', 1, 'A terminal alkyne has the triple bond:', 'At the end of the chain', ['In the middle of the chain', 'In a ring', 'Next to a double bond'], 'A terminal alkyne has an H on a triple-bond carbon.')
    b.mc('9.2', 2, 'Which is an internal alkyne?', 'Pent-2-yne', ['Pent-1-yne', 'Ethyne', 'Propyne'], 'Both triple-bond carbons are bonded to other carbons.')
    # ------------------------------------------------------------ 9.3 Acidity
    b.mc('9.3', 1, 'Which hydrogen is the most acidic?', 'The terminal alkyne C-H', ['An alkene C-H', 'An alkane C-H', 'They are equally acidic'], 'The sp carbon holds its lone pair closest to the nucleus.', img=S('C#CCC=C'))
    b.mc('9.3', 2, 'Why is the conjugate base of a terminal alkyne relatively stable?', 'The lone pair is in an sp orbital, which has high s character', ['The lone pair is in a p orbital', 'The anion is delocalised by resonance', 'The anion is a radical'], 'Electrons in an sp orbital are held close to the nucleus.')
    b.mc('9.3', 2, 'Which base is strong enough to deprotonate a terminal alkyne completely?', 'NaNH₂', ['NaOH', 'NaOCH₃', 'NaHCO₃'], 'The amide ion is a stronger base than the alkynide ion that forms.')
    b.mc('9.3', 3, 'Which compound cannot be deprotonated by NaNH₂ at a triple-bond carbon?', 'But-2-yne', ['Propyne', 'But-1-yne', 'Acetylene'], 'An internal alkyne has no acidic C-H on the triple bond.')
    b.mc('9.3', 3, 'The reaction of propyne with NaNH₂ gives:', 'The propynide ion (an alkynide) and NH₃', ['Propene and NaNH', 'A vinyl anion', 'Propane'], 'The base removes the acidic proton.')
    # ------------------------------------------------------------ 9.4 Preparation
    b.mc('9.4', 1, 'An alkyne can be prepared from a dihalide by:', 'Two successive E2 reactions', ['Two SN2 reactions', 'Hydrogenation', 'Ozonolysis'], 'Each E2 removes one HX.')
    b.mc('9.4', 2, 'Which is a suitable starting material to make propyne by double elimination?', '1,2-Dibromopropane', ['1-Bromopropane', '2-Bromopropane', 'Propane'], 'A vicinal dihalide loses two HBr.', img=S('CC(Br)CBr'))
    b.mc('9.4', 3, 'Why is excess (three equivalents of) NaNH₂ needed when making a terminal alkyne from a dihalide?', 'The terminal alkyne product is deprotonated by the base, and water workup restores it', ['The first E2 is very slow', 'NaNH₂ is destroyed by the solvent', 'A radical must be generated'], 'The third equivalent deprotonates the terminal alkyne; protonation on workup gives the alkyne.')
    b.mc('9.11', 3, 'Which two-step sequence converts but-1-ene into but-1-yne?', '(1) Br₂; (2) excess NaNH₂, then H₂O', ['(1) HBr; (2) NaOH', '(1) H₂, Pt; (2) NaNH₂', '(1) O₃; (2) DMS'], 'Bromination makes a vicinal dibromide, which eliminates twice.', img=S('C=CCC'))
    # ------------------------------------------------------------ 9.5 Reduction
    b.mcstruct('9.5', 2, "What is the major product of but-2-yne with H₂ and Lindlar's catalyst?", CIS, [TRANS, 'CCCC', 'CC(C)C'], 'A poisoned catalyst stops at the alkene and adds H₂ syn, giving the cis alkene.')
    b.mcstruct('9.5', 2, 'What is the major product of but-2-yne with Na in liquid NH₃?', TRANS, [CIS, 'CCCC', 'CC#C'], 'Dissolving-metal reduction gives the trans alkene.')
    b.mcstruct('9.5', 1, 'What is the product of but-2-yne with excess H₂ and Pt?', 'CCCC', [CIS, TRANS, 'CC(C)C'], 'Without a poison the alkene is also hydrogenated to the alkane.')
    b.mc('9.5', 2, 'Which reagent converts an internal alkyne into a cis alkene?', 'H₂, Lindlar catalyst', ['Na, NH₃(l)', 'H₂, Pt', 'O₃, then H₂O'], 'Lindlar catalyst is poisoned Pd.')
    b.mc('9.5', 3, 'The Na/NH₃ reduction of an alkyne involves which kind of arrow?', 'Fishhook (single-electron) arrows', ['Only full-headed arrows', 'No arrows', 'Equilibrium arrows'], 'Electrons are transferred one at a time through a radical anion.')
    b.mc('9.5', 3, 'Which reagent converts pent-2-yne into trans-pent-2-ene?', 'Na, NH₃(l)', ['H₂, Lindlar', 'H₂ (excess), Pd/C', 'BH₃ then H₂O₂'], 'Dissolving-metal reduction gives trans alkenes.', img=S('CC#CCC'))
    # ------------------------------------------------------------ 9.6 Hydrohalogenation
    b.mcstruct('9.6', 2, 'What is the product of propyne with one equivalent of HBr?', 'C=C(C)Br', ['CC=CBr', 'CC(C)(Br)Br', 'CCCBr'], 'Markovnikov: bromine on the more substituted alkyne carbon.')
    b.mcstruct('9.6', 3, 'What is the product of propyne with two equivalents of HBr?', 'CC(C)(Br)Br', ['CC(Br)CBr', 'BrCC(Br)CBr', 'C=C(C)Br'], 'The second HBr adds to the same carbon, giving a geminal dibromide.')
    b.mcstruct('9.6', 3, 'What is the product of propyne with HBr in the presence of peroxides?', 'CC=CBr', ['C=C(C)Br', 'CC(C)(Br)Br', 'CC(Br)CBr'], 'Peroxides give anti-Markovnikov addition.')
    b.mc('9.6', 3, 'Two equivalents of HX add to a terminal alkyne. Where are the two halogens in the product?', 'On the same carbon (geminal)', ['On adjacent carbons', 'On the terminal carbon only', 'On carbons 1 and 3'], 'Both additions are Markovnikov.')
    # ------------------------------------------------------------ 9.7 Hydration
    b.mcstruct('9.7', 3, 'What is the product of but-1-yne with H₂O, H₂SO₄, HgSO₄?', 'CCC(C)=O', ['CCCC=O', 'CCC(C)O', 'CC=CC'], 'Markovnikov hydration gives an enol that tautomerizes to a ketone.')
    b.mcstruct('9.7', 3, 'What is the product of but-1-yne with (1) Sia₂BH; (2) H₂O₂, NaOH?', 'CCCC=O', ['CCC(C)=O', 'CCCCO', 'CCC(C)O'], 'Anti-Markovnikov hydration of a terminal alkyne gives an aldehyde.')
    b.mc('9.7', 1, 'Enols and ketones that interconvert are called:', 'Tautomers', ['Enantiomers', 'Resonance structures', 'Diastereomers'], 'Tautomers are constitutional isomers that interconvert by moving a proton.')
    b.mc('9.7', 2, 'What functional group does an enol contain?', 'A C=C double bond bearing an OH group', ['A C=O and an OH', 'A C≡C and an OH', 'Two OH groups'], 'Enol means ene + ol.', img=S('C=C(C)O'))
    b.mc('9.7', 2, 'Hydration of an internal symmetrical alkyne such as but-2-yne gives:', 'A single ketone', ['An aldehyde', 'A mixture of two ketones', 'A carboxylic acid'], 'Both carbons give the same product.')
    b.mc('9.7', 3, 'Hydration of pent-2-yne (HgSO₄, H₂SO₄, H₂O) gives:', 'A mixture of two ketones', ['A single ketone', 'An aldehyde', 'An alcohol'], 'Water can add to either alkyne carbon with similar preference.', img=S('CC#CCC'))
    b.mc('9.7', 4, 'The tautomerization of an enol to a ketone in base proceeds through:', 'An enolate ion', ['A carbocation', 'A radical', 'A carbene'], 'Deprotonation of the enol gives a resonance-stabilised enolate, which is protonated on carbon.')
    # ------------------------------------------------------------ 9.8 / 9.9
    b.mcstruct('9.8', 2, 'What is the product of propyne with excess Br₂?', 'CC(Br)(Br)C(Br)Br', ['CC(Br)=C(Br)Br', 'CC(Br)C(Br)', 'C=CC'], 'Each π bond adds one Br₂, giving a tetrabromide.')
    b.mc('9.8', 3, 'How many moles of Br₂ add to one mole of an alkyne to give a tetrabromide?', '2', ['1', '3', '4'], 'Each of the two π bonds adds one Br₂.')
    b.mc('9.9', 1, 'Ozonolysis of an internal alkyne (O₃; H₂O) gives:', 'Two carboxylic acids', ['Two aldehydes', 'Two ketones', 'Two alcohols'], 'Each alkyne carbon becomes a carboxylic acid carbon.')
    b.mcstruct('9.9', 2, 'What is formed from but-2-yne with (1) O₃; (2) H₂O?', 'CC(=O)O', ['CC=O', 'CC(C)=O', 'CCO'], 'Two molecules of acetic acid form.')
    b.mc('9.9', 3, 'Ozonolysis of a terminal alkyne converts the terminal carbon into:', 'CO₂', ['A methyl group', 'An aldehyde', 'An alcohol'], 'The terminal CH becomes carbon dioxide.')
    # ------------------------------------------------------------ 9.10 Alkylation
    b.mc('9.10', 1, 'In the alkylation of a terminal alkyne, the nucleophile is:', 'The alkynide ion', ['The alkyl halide', 'The alkyne itself', 'NaNH₂'], 'The anion attacks the alkyl halide in an SN2 reaction.')
    b.mcstruct('9.10', 3, 'What is the product of but-1-yne with (1) NaNH₂; (2) CH₃CH₂Br?', 'CCC#CCC', ['CC#CC', 'CCC#C', 'CCC=CCC'], 'The alkynide attacks the primary halide in an SN2 reaction, adding two carbons.')
    b.mc('9.10', 3, 'Which alkyl halide gives the best yield of alkylation with an alkynide?', 'Methyl or primary', ['Tertiary', 'Secondary', 'Vinylic'], 'The alkynide is also a strong base, so only SN2-reactive halides work.')
    b.mc('9.10', 4, 'What is the main product when an alkynide reacts with tert-butyl bromide?', 'The alkene from E2 elimination', ['The alkylated alkyne', 'A ketone', 'The alkane'], 'A strong base with a tertiary halide gives elimination.')
    # ------------------------------------------------------------ 9.11 Synthesis
    b.mc('9.11', 3, 'To make hex-3-yne from acetylene, you need:', 'Two alkylations with ethyl bromide', ['Two hydrations', 'One hydrogenation', 'Ozonolysis'], 'NaNH₂ then CH₃CH₂Br, repeated twice.')
    b.mc('9.11', 3, 'To convert but-2-yne to butan-2-one, use:', 'H₂O, H₂SO₄, HgSO₄', ['H₂, Lindlar', 'Na, NH₃', 'O₃, H₂O'], 'Hydration of an alkyne gives a ketone through an enol.', img=S('CC#CC'))
    b.mc('9.11', 4, 'To convert 1-butyne into 2-pentyne (chain extension), which sequence is best?', '(1) NaNH₂; (2) CH₃I', ['(1) H₂, Lindlar; (2) CH₃I', '(1) HBr; (2) NaNH₂', '(1) Br₂; (2) CH₃I'], 'Deprotonate the terminal alkyne and alkylate with methyl iodide.', img=S('CCC#C'))
    b.mc('9.11', 4, 'To convert 1-bromopropane into propyne, the best sequence is:', '(1) NaOEt; (2) Br₂; (3) excess NaNH₂, then H₂O', ['(1) NaNH₂; (2) H₂O', '(1) Br₂; (2) H₂O', '(1) H₂, Pt; (2) NaNH₂'], 'Eliminate to propene, brominate, then double elimination.', img=S('CCCBr'))

    b.mc('9.8', 2, 'What is the stereochemistry of the addition of one equivalent of Br₂ to an alkyne?', 'Anti', ['Syn', 'Markovnikov', 'Radical only'], 'A bromonium ion is opened from the opposite face.', img=S('CC#CC'))
    # ================================================================ free response
    b.fr('9.1', 1, 'Describe the bonds in a carbon-carbon triple bond.', 'One σ bond and two π bonds, formed by sp hybridized carbons.', 'Three bonds in total.')
    b.fr('9.1', 2, 'What is the geometry around the carbons of an alkyne, and why?', 'Linear (180°); each carbon is sp hybridised with two σ bonds spread as far apart as possible.', 'Two electron regions.')
    b.fr('9.1', 2, 'Draw the structural formula of propyne and label the bond angle at the central carbon.', 'CH₃-C≡CH with a 180° C-C≡C angle.', 'Linear.', aimg=S('CC#C'))
    b.fr('9.2', 1, 'Define terminal and internal alkynes.', 'A terminal alkyne has its triple bond at the end of a chain (with an acidic C-H); an internal alkyne has the triple bond within the chain.', 'Position of the triple bond.')
    b.fr('9.2', 2, 'Name the compound shown.', '4-Methylpent-2-yne', 'Number from the end nearest the triple bond.', img=S('CC#CC(C)C'))
    b.fr('9.2', 2, 'Draw pent-1-yne and pent-2-yne.', 'Pent-1-yne: HC≡C-CH₂CH₂CH₃. Pent-2-yne: CH₃-C≡C-CH₂CH₃.', 'Same formula, different triple bond position.', aimg=S('C#CCCC', 'CC#CCC', labels='1-yne 2-yne'))
    b.fr('9.2', 3, 'Name the compound shown.', '2,5-Dimethylhept-3-yne', 'The triple bond must receive the lowest locant.', img=S('CCC(C)C#CC(C)C'))
    b.fr('9.2', 3, 'Draw all acyclic alkynes of formula C₅H₈ and name them.', 'Pent-1-yne, pent-2-yne and 3-methylbut-1-yne.', 'Check the positions of the triple bond and branching.', aimg=S('C#CCCC', 'CC#CCC', 'C#CC(C)C'))
    b.fr('9.2', 1, 'Draw ethyne (acetylene) and give its common name.', 'HC≡CH; the common name is acetylene.', 'Simplest alkyne.', aimg=S('C#C'))
    b.fr('9.3', 1, 'Which C-H bond of a hydrocarbon is the most acidic: alkane, alkene or terminal alkyne?', 'The terminal alkyne C-H.', 'sp carbon is the most electron-withdrawing.')
    b.fr('9.3', 2, 'Explain why a terminal alkyne is more acidic than an alkene.', 'The conjugate base has its lone pair in an sp orbital (50% s character), which holds electrons closer to the nucleus and stabilises the anion.', 'Orbital hybridization.')
    b.fr('9.3', 2, 'Write the reaction of propyne with NaNH₂.', 'CH₃C≡CH + NaNH₂ → CH₃C≡C⁻ Na⁺ + NH₃.', 'The amide removes the acidic proton.')
    b.fr('9.3', 3, 'Why can NaOH not be used to deprotonate a terminal alkyne completely?', 'Hydroxide is a weaker base than the alkynide ion, so the equilibrium lies on the side of the reactants.', 'Compare base strengths.')
    b.fr('9.3', 3, 'Which compound will react with NaNH₂ to form an alkynide, but-1-yne or but-2-yne? Explain.', 'But-1-yne has an acidic hydrogen on the terminal sp carbon; but-2-yne has none.', 'Look for a hydrogen on the triple bond carbon.')
    b.fr('9.4', 2, 'Give the starting material and reagents to prepare propyne by double elimination.', '1,2-Dibromopropane (or 2,2-dibromopropane) with excess NaNH₂, then H₂O.', 'Two E2 reactions.', img=S('CC(Br)CBr'))
    b.fr('9.4', 3, 'Why are three equivalents of NaNH₂ used when making a terminal alkyne from a dihalide?', 'Two eliminate HX; the third deprotonates the terminal alkyne (it is acidic), and a water workup restores the alkyne.', 'The product is acidic.')
    b.fr('9.4', 3, 'Show how to prepare but-2-yne from 2,3-dibromobutane.', 'Treat with excess NaNH₂ (or NaOH at high T): two successive E2 reactions.', 'Vicinal dihalide.', img=S('CC(Br)C(Br)C'), aimg=S('CC#CC'))
    b.fr('9.5', 1, 'What does H₂ with Pt do to an alkyne?', 'It reduces it fully to an alkane.', 'Two additions of H₂.')
    b.fr('9.5', 2, 'Draw the product of but-2-yne with H₂ and Lindlar catalyst.', 'cis-But-2-ene (syn addition of H₂).', 'Poisoned catalyst, syn.', img=S('CC#CC'), aimg=S(CIS))
    b.fr('9.5', 2, 'Draw the product of but-2-yne with Na, NH₃(l).', 'trans-But-2-ene.', 'Dissolving-metal reduction.', img=S('CC#CC'), aimg=S(TRANS))
    b.fr('9.5', 3, 'What type of arrow is used in the mechanism of the dissolving-metal reduction, and why?', 'Fishhook (single-headed) arrows, because only one electron moves at a time (from sodium to the alkyne).', 'Radical anion intermediate.')
    b.fr('9.5', 3, 'Propose reagents to convert pent-2-yne to cis-pent-2-ene, and to trans-pent-2-ene.', 'cis: H₂, Lindlar catalyst. trans: Na, NH₃(l).', 'Syn vs dissolving metal.', img=S('CC#CCC'), aimg=S('C/C=C\\CC', 'C/C=C/CC', labels='cis trans'))
    b.fr('9.5', 4, 'Explain why an alkyne can be stopped at the alkene stage with Lindlar catalyst but not with Pd/C.', 'The poisoned catalyst is too unreactive to hydrogenate the alkene once formed, while unpoisoned Pd/C hydrogenates the alkene to an alkane.', 'Catalyst activity.')
    b.fr('9.6', 1, 'State the regiochemistry for the addition of HBr to a terminal alkyne.', 'Markovnikov: bromine ends up on the internal (more substituted) carbon.', 'More stable cationic character.')
    b.fr('9.6', 2, 'Draw the product of propyne with one equivalent of HBr.', '2-Bromopropene.', 'Markovnikov.', img=S('CC#C'), aimg=S('C=C(C)Br'))
    b.fr('9.6', 2, 'Draw the product of propyne with two equivalents of HBr.', '2,2-Dibromopropane (geminal dibromide).', 'Both Br on the same carbon.', img=S('CC#C'), aimg=S('CC(C)(Br)Br'))
    b.fr('9.6', 3, 'Draw the product of propyne with HBr and peroxides and state the regiochemistry.', '1-Bromopropene; anti-Markovnikov (radical addition).', 'Peroxides.', img=S('CC#C'), aimg=S('CC=CBr'))
    b.fr('9.7', 1, 'What is tautomerism?', 'The rapid interconversion of constitutional isomers by movement of a proton, such as an enol and a ketone.', 'Keto-enol.')
    b.fr('9.7', 2, 'Draw the enol and ketone formed from propyne with H₂O, H₂SO₄, HgSO₄.', 'Enol: CH₃C(OH)=CH₂; it tautomerizes to acetone, CH₃C(=O)CH₃.', 'Markovnikov hydration.', img=S('CC#C'), aimg=S('C=C(C)O', 'CC(C)=O'))
    b.fr('9.7', 2, 'Draw the product of but-1-yne with (1) Sia₂BH; (2) H₂O₂, NaOH.', 'Butanal (an aldehyde).', 'Anti-Markovnikov, then tautomerization.', img=S('CCC#C'), aimg=S('CCCC=O'))
    b.fr('9.7', 3, 'Explain why hydration of but-1-yne gives a ketone but hydroboration-oxidation gives an aldehyde.', 'Acid-catalyzed hydration is Markovnikov (OH on C2, giving a ketone); hydroboration is anti-Markovnikov (OH on C1, giving an aldehyde).', 'Regiochemistry.')
    b.fr('9.7', 3, 'Why does hydration of pent-2-yne give two products?', 'The alkyne is unsymmetrical with similar substituents on each side, so water adds to either carbon, giving pentan-2-one and pentan-3-one.', 'Compare the two sides.', img=S('CC#CCC'), aimg=S('CC(=O)CCC', 'CCC(=O)CC'))
    b.fr('9.7', 4, 'Describe the base-catalyzed tautomerization of an enol to a ketone.', 'Hydroxide removes the enol O-H proton, forming a resonance-stabilised enolate; the carbon of the enolate then takes a proton from water to give the ketone.', 'Enolate intermediate.')
    b.fr('9.8', 2, 'Draw the product of propyne with excess Br₂.', '1,1,2,2-Tetrabromopropane.', 'Two Br₂ add.', img=S('CC#C'), aimg=S('CC(Br)(Br)C(Br)Br'))
    b.fr('9.8', 3, 'How many equivalents of Br₂ are needed to convert an alkyne to a tetrabromide, and why?', 'Two, since each of the two π bonds adds one Br₂.', 'Two π bonds.')
    b.fr('9.9', 2, 'Draw the products of but-2-yne with (1) O₃; (2) H₂O.', 'Two molecules of acetic acid.', 'Internal alkynes give carboxylic acids.', img=S('CC#CC'), aimg=S('CC(=O)O'))
    b.fr('9.9', 3, 'Draw the products of but-1-yne with (1) O₃; (2) H₂O.', 'Propanoic acid and carbon dioxide.', 'The terminal carbon becomes CO₂.', img=S('CCC#C'), aimg=S('CCC(=O)O', 'O=C=O'))
    b.fr('9.9', 4, 'An alkyne gives acetic acid and propanoic acid on ozonolysis with water workup. Identify it.', 'Pent-2-yne.', 'Join the two acid carbons.', aimg=S('CC#CCC'))
    b.fr('9.10', 1, 'What is alkylation of a terminal alkyne?', 'Formation of a new C-C bond by reacting an alkynide with an alkyl halide in an SN2 reaction.', 'Alkynide as nucleophile.')
    b.fr('9.10', 2, 'Draw the product of propyne with (1) NaNH₂; (2) CH₃CH₂Br.', 'Pent-2-yne.', 'SN2 on a primary halide.', img=S('CC#C'), aimg=S('CC#CCC'))
    b.fr('9.10', 3, 'Explain why tertiary alkyl halides cannot be used in alkynide alkylation.', 'The alkynide is a strong base, so with a tertiary halide E2 elimination occurs instead of SN2.', 'Strong base, hindered halide.')
    b.fr('9.10', 3, 'Show how to make hex-3-yne from acetylene.', '(1) NaNH₂; (2) CH₃CH₂Br; (3) NaNH₂; (4) CH₃CH₂Br.', 'Alkylate twice.', img=S('C#C'), aimg=S('CCC#CCC'))
    b.fr('9.11', 3, 'Propose a synthesis of but-1-yne from but-1-ene.', '(1) Br₂; (2) excess NaNH₂; (3) H₂O.', 'Add Br₂, then eliminate twice.', img=S('C=CCC'), aimg=S('CCC#C'))
    b.fr('9.11', 3, 'Propose a synthesis of butan-2-one from but-1-yne.', 'H₂O, H₂SO₄, HgSO₄ (Markovnikov hydration, then tautomerization).', 'Ketone.', img=S('CCC#C'), aimg=S('CCC(C)=O'))
    b.fr('9.11', 4, 'Propose a synthesis of cis-pent-2-ene from propyne and ethyl bromide.', '(1) NaNH₂; (2) CH₃CH₂Br to give pent-2-yne; (3) H₂, Lindlar catalyst to give cis-pent-2-ene.', 'Alkylate, then partially reduce.', img=S('CC#C'), aimg=S('C/C=C\\CC'))
    b.fr('9.11', 4, 'Propose a synthesis of trans-hex-3-ene from acetylene and ethyl bromide.', '(1) NaNH₂; (2) CH₃CH₂Br; (3) NaNH₂; (4) CH₃CH₂Br to give hex-3-yne; (5) Na, NH₃(l) to give the trans alkene.', 'Build then dissolving-metal reduction.', img=S('C#C'), aimg=S('CC/C=C/CC'))
    b.fr('9.11', 4, 'Propose a synthesis of 2,2-dibromopropane from propene.', '(1) Br₂; (2) excess NaNH₂, then H₂O to give propyne; (3) 2 HBr.', 'Alkyne then double HBr addition.', img=S('C=CC'), aimg=S('CC(C)(Br)Br'))
    b.fr('9.5', 3, 'Why is a trans alkene formed in the dissolving-metal reduction?', 'The intermediate vinylic radical prefers the more stable trans arrangement, which places the large groups far apart before the second reduction and protonation.', 'Stability of the intermediate.')
    b.fr('9.2', 2, 'How many carbons are in hex-2-yne, and where is the triple bond?', 'Six carbons; the triple bond is between C2 and C3.', 'The locant gives the first carbon of the triple bond.')
    b.fr('9.8', 2, 'Draw the product of but-2-yne with one equivalent of Br₂ and state the stereochemistry of addition.', '(E)-2,3-Dibromobut-2-ene, formed by anti addition.', 'Bromination of an alkyne is anti, like an alkene.', img=S('CC#CC'), aimg=S('C/C(Br)=C(/C)Br'))
